#include <cmath>
#include <algorithm>
#include <random>
#include <vector>
extern "C" {
struct Stroke {float x,y,ang,len,w; int col; float gain;};
static std::mt19937 rng(41);
float ur(){return std::uniform_real_distribution<float>(0,1)(rng);} 
float norm(){return std::normal_distribution<float>(0,1)(rng);}
float eval(Stroke &s,float* C,float*T,float*pal,int N,bool apply){
 float cs=cos(s.ang),sn=sin(s.ang),r=s.w/2, hl=s.len/2;
 int x0=std::max(0,int(s.x-fabs(cs)*hl-r-2)),x1=std::min(N-1,int(s.x+fabs(cs)*hl+r+2));
 int y0=std::max(0,int(s.y-fabs(sn)*hl-r-2)),y1=std::min(N-1,int(s.y+fabs(sn)*hl+r+2));
 double aa=0,b[3]={},d[3]={};
 for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){
  float xx=x-s.x,yy=y-s.y,u=xx*cs+yy*sn,v=-xx*sn+yy*cs;
  float e=std::max(0.f,fabs(u)-hl); float dist=sqrt(e*e+v*v);
  float a=std::clamp((r+.8f-dist)/1.6f,0.f,1.f); if(a==0)continue;
  float weight=(x<9||y<9||x>N-10||y>N-10)?.3f:1.f;
  int i=(y*N+x)*3;
  if(apply){for(int k=0;k<3;k++)C[i+k]=C[i+k]*(1-a)+pal[s.col*3+k]*a;continue;}
  aa+=a*a*weight;
  for(int k=0;k<3;k++) {float c=C[i+k],t=T[i+k]; b[k]+=weight*(a*(c-t)-a*a*c); d[k]+=weight*(2*a*c*(c-t)-a*a*c*c);}
 }
 if(apply)return 0;
 float best=-1e30;int col=0;
 for(int p=0;p<16;p++) {double gain=0;for(int k=0;k<3;k++){float v=pal[p*3+k];gain+=d[k]-2*v*b[k]-aa*v*v;}if(gain>best){best=gain;col=p;}}
 s.col=col;s.gain=best;return best;
}
void pick(float*C,float*T,float*pal,int N,int iteration,float*out){
 std::vector<Stroke> best;
 int n=iteration<80?3500:2000;
 for(int i=0;i<n;i++){
  Stroke s; s.x=ur()*(N-10)+5;s.y=ur()*(N-10)+5;s.ang=ur()*3.14159;
  s.w=(5.5+ur()*6)*N/227.18;
  s.len=(5+pow(ur(),2)*(iteration<100?220:100))*N/227.18;
  eval(s,C,T,pal,N,0);
  if(best.size()<16){best.push_back(s);std::sort(best.begin(),best.end(),[](Stroke a,Stroke b){return a.gain>b.gain;});}
  else if(s.gain>best.back().gain){best.back()=s;std::sort(best.begin(),best.end(),[](Stroke a,Stroke b){return a.gain>b.gain;});}
 }
 for(auto &b:best){
  for(int j=0;j<220;j++){
   Stroke s=b;float scale=j<70?8:j<140?3:1;
   int m=int(ur()*6);
   if(m<2){s.x+=norm()*scale;s.y+=norm()*scale;}
   else if(m==2)s.ang+=norm()*scale*.025;
   else if(m==3)s.len+=norm()*scale*2;
   else if(m==4)s.w+=norm()*scale*.4;
   else{s.x+=norm()*scale;s.y+=norm()*scale;s.len+=norm()*scale;s.ang+=norm()*scale*.015;}
   s.x=std::clamp(s.x,3.f,N-4.f);s.y=std::clamp(s.y,3.f,N-4.f);
   s.w=std::clamp(s.w,5.3f*N/227.18f,11.5f*N/227.18f);s.len=std::clamp(s.len,3.f*N/227.18f,220.f*N/227.18f);
   float dx=cos(s.ang)*s.len/2,dy=sin(s.ang)*s.len/2;
   if(s.x-fabs(dx)<2||s.x+fabs(dx)>N-3||s.y-fabs(dy)<2||s.y+fabs(dy)>N-3)continue;
   eval(s,C,T,pal,N,0);if(s.gain>b.gain)b=s;
  }
 }
 auto b=*std::max_element(best.begin(),best.end(),[](Stroke a,Stroke b){return a.gain<b.gain;});
 out[0]=b.x;out[1]=b.y;out[2]=b.ang;out[3]=b.len;out[4]=b.w;out[5]=b.col;out[6]=b.gain;
 eval(b,C,T,pal,N,1);
}
}
